// === Tab: cell.js ===
class Cell {
  constructor(i, j) {
    this.i = i;
    this.j = j;
    this.walls = [true, true, true, true]; // top, right, bottom, left
    this.visited = false;
    this.forceBlock = false;
  }

  checkNeighbors() {
    const neighbors = [];

    const i = this.i;
    const j = this.j;
    const top = grid[index(i, j - 1)];
    const right = grid[index(i + 1, j)];
    const bottom = grid[index(i, j + 1)];
    const left = grid[index(i - 1, j)];

    [top, right, bottom, left].forEach((n) => {
      if (n && !n.visited) {
        neighbors.push(n);
      }
    });

    if (neighbors.length > 0) {
      const r = floor(random(neighbors.length));
      return neighbors[r];
    } else {
      return undefined;
    }
  }

  highlight() {
    const x = this.i * w + sW/2;
    const y = this.j * w + sW/2;
    noStroke();

    fill('red');
    square(x, y, w-sW);
  }

  show() {
    const x = this.i * w;
    const y = this.j * w;

    if (this.visited && !this.forceBlock) {
      noStroke();
      // stroke(30)
      fill(220);
      square(x, y, w);
    }

    this.showLine();
  }

  showLine() {
    const x = this.i * w;
    const y = this.j * w;

    stroke(30);
    const walls = this.walls;
    if (walls[0]) {
      line(x, y, x + w, y);
    }
    if (walls[1]) {
      line(x + w, y, x + w, y + w);
    }
    if (walls[2]) {
      line(x, y + w, x + w, y + w);
    }
    if (walls[3]) {
      line(x, y, x, y + w);
    }
  }
}


