// Reference: https://thecodingtrain.com/CodingChallenges/010.1-maze-dfs-p5.html
// by Daniel Shiffman

const W = 720;
const sW = 12; // stroke weight
const cols = 24;
const rows = cols;
const w = W / rows; // size of a cell

const grid = [];

let current;

const stack = [];

function setup() {
  createCanvas(W, W);
  prepareTexture(width, height);
  // frameRate(30);

  strokeWeight(sW);

  prepareCells();
  addCharCells();
}

const prepareCells = () => {
  for (let j = 0; j < rows; j++) {
    for (let i = 0; i < cols; i++) {
      const cell = new Cell(i, j);
      grid.push(cell);
    }
  }

  current = grid[0];
};

const addCharCells = () => {
  addChar(5, 3, chardata.A);
  addChar(9, 3, chardata.l);
  addChar(12, 3, chardata.t);
  addChar(5, 9, chardata.E);
  addChar(9, 9, chardata.d);
  addChar(13, 9, chardata.u);
  addChar(5, 15, chardata.n2);
  addChar(9, 15, chardata.n0);
  addChar(13, 15, chardata.n2);
  addChar(17, 15, chardata.n2);
};

const addChar = (i, j, data) => {
  for (let k = 0; k < 5; k++) {
    for (let l = 0; l < 3; l++) {
      const cell = grid[(j + k) * cols + i + l];
      if (data[k][l] === 1) {
        cell.visited = true;
        cell.forceBlock = true;
      } else if (data[k][l] === 2) {
        cell.visited = true;
      }
    }
  }
};

function draw() {
  background(30);

  grid.forEach((cell) => {
    cell.show();
  });

  grid.forEach((cell) => {
    cell.showLine();
  });

  current.visited = true;
  current.highlight();
  const next = current.checkNeighbors();
  if (next) {
    // STEP 1
    next.visited = true;

    // STEP 2
    stack.push(current);

    // STEP 3
    removeWalls(current, next);

    // SETP 4
    current = next;
  } else if (stack.length > 0) {
    current = stack.pop();
  }

  // Draw texture
  image(textureGfx, 0, 0);
}

const index = (i, j) => {
  if (i < 0 || j < 0 || i > cols - 1 || j > rows - 1) {
    return -1;
  }

  return i + j * cols;
};

const removeWalls = (a, b) => {
  const x = a.i - b.i;
  const y = a.j - b.j;

  if (x === 1) {
    a.walls[3] = false;
    b.walls[1] = false;
  } else if (x === -1) {
    a.walls[1] = false;
    b.walls[3] = false;
  }

  if (y === 1) {
    a.walls[0] = false;
    b.walls[2] = false;
  } else if (y === -1) {
    a.walls[2] = false;
    b.walls[0] = false;
  }
};


